  async function fetchCurrentRatesData() {
    const results = {}
    for (const { from, to } of RATE_PAIRS) {
      const { data } = await supabase
        .from('exchange_rates')
        .select('rate, fetched_at')
        .eq('from_currency', from)
        .eq('to_currency', to)
        .order('fetched_at', { ascending: false })
        .limit(1)
      if (data?.[0]) results[`${from}-${to}`] = data[0]
    }
    setCurrentRatesData(results)
    const inputs = {}
    for (const { from, to } of RATE_PAIRS) {
      const key = `${from}-${to}`
      if (results[key]) inputs[key] = String(results[key].rate)
    }
    setRateInputs(prev => ({ ...inputs, ...prev }))
  }

  async function handleSaveRate(from, to, value) {
    const num = parseFloat(value)
    if (!num || num <= 0) return
    const key = `${from}-${to}`
    setSavingRate(key)
    try {
      const { error } = await supabase.from('exchange_rates').insert({
        from_currency: from, to_currency: to, rate: num,
        fetched_at: new Date().toISOString(),
      })
      if (error) throw error
      setRateMsg(`${from} → ${to} set to ${num}`)
      setTimeout(() => setRateMsg(''), 4000)
      fetchCurrentRatesData()
      if (from === 'USD' && to === 'CNY') refetchUsdCny()
      if (from === 'HKD' && to === 'EUR') refetchHkdEur()
      if (from === 'EUR' && to === 'USD') refetchEurUsd()
    } catch (e) { alert('Failed to save: ' + e.message) }
    setSavingRate(null)
  }

  const CURRENCY_SYMBOLS = { EUR: '€', USD: '$', CNY: '¥', HKD: 'HK$' }

  async function approveSupplierListing(listing) {
    const rd = supReviewData[listing.id] || {}
    if (!rd.price) { alert('Set a selling price before approving.'); return }
    const cur = rd.currency || 'EUR'
    const sym = CURRENCY_SYMBOLS[cur] || cur + ' '
    if (!window.confirm(`Approve and publish as preorder at ${sym}${rd.price}?`)) return

    let priceEur, priceUsd
    const num = Number(rd.price)
    if (cur === 'USD') {
      priceUsd = num
      priceEur = rate ? Math.round(num / rate) : num
    } else if (cur === 'CNY') {
      priceEur = (usdToCnyRate && rate) ? Math.round(num / usdToCnyRate / rate) : num
      priceUsd = priceEur && rate ? Math.round(priceEur * rate) : null
    } else if (cur === 'HKD') {
      priceEur = hkdToEurRate ? Math.round(num * hkdToEurRate) : num
      priceUsd = priceEur && rate ? Math.round(priceEur * rate) : null
    } else {
      priceEur = num
      priceUsd = rate ? Math.round(num * rate) : null
    }

    const askingCur = listing.asking_price_currency || 'CNY'
    const askingAmt = listing.asking_price ? Number(listing.asking_price) : null
    let costEur = null
    if (askingAmt) {
      if (askingCur === 'EUR') costEur = askingAmt
      else if (askingCur === 'CNY' && usdToCnyRate && rate) costEur = Math.round(askingAmt / usdToCnyRate / rate)
      else if (askingCur === 'HKD' && hkdToEurRate) costEur = Math.round(askingAmt * hkdToEurRate)
      else if (askingCur === 'USD' && rate) costEur = Math.round(askingAmt / rate)
    }

    const isJewellery = listing.category === 'Jewellery'
    // For jewellery: encode stone + size into notes if present
    let notesForPreorder = listing.notes || null
    if (isJewellery) {
      const extras = [listing.stone, listing.size_info].filter(Boolean).join(' · ')
      notesForPreorder = [listing.notes, extras].filter(Boolean).join('\n') || null
    }
    const { data: preorder, error: pErr } = await supabase.from('preorders').insert({
      brand: isJewellery ? (listing.brand || listing.jewellery_type || 'Jewellery') : listing.brand,
      model: isJewellery ? (listing.model || listing.jewellery_type || '') : listing.model,
      reference: isJewellery ? null : (listing.reference || null),
      condition: listing.condition || 'Pre-owned',
      scope_of_delivery: isJewellery ? null : (listing.scope_of_delivery || null),
      notes: notesForPreorder,
      price_eur: priceEur,
      price_usd: priceUsd,
      cost_eur: costEur,
      vendor: listing.profiles?.full_name || null,
      category: isJewellery ? 'Jewellery' : 'Watches',
      subcategory: isJewellery ? (listing.jewellery_type || null) : null,
      metal_type: isJewellery ? (listing.metal || null) : null,
      posted_by: profile.id,
      status: 'available',
    }).select().single()
    if (pErr) { alert('Failed to create preorder: ' + pErr.message); return }
    const imgs = (listing.supplier_listing_images || []).sort((a, b) => a.position - b.position)
    for (const img of imgs) {
      await supabase.from('preorder_images').insert({ preorder_id: preorder.id, url: img.url, position: img.position })
    }
    await supabase.from('supplier_listings').update({
      status: 'approved',
      selling_price: Number(rd.price),
      reviewed_by: profile.id,
      reviewed_at: new Date().toISOString(),
      preorder_id: preorder.id,
    }).eq('id', listing.id)
    fetchSupplierListings()
    fetchPreorders(0, listingType, search)
  }

