  async function saveSupplierListingEdit(listingId) {
    const listing = supplierListings.find(l => l.id === listingId)
    const isJewellery = listing?.category === 'Jewellery'
    const updatedFields = {
      brand: supEditForm.brand,
      model: supEditForm.model,
      condition: supEditForm.condition || null,
      asking_price: supEditForm.asking_price ? Number(supEditForm.asking_price) : null,
      notes: supEditForm.notes || null,
      // Watch-specific
      reference: isJewellery ? (listing?.reference || null) : (supEditForm.reference || null),
      scope_of_delivery: isJewellery ? null : (supEditForm.scope_of_delivery || null),
      // Jewellery-specific
      jewellery_type: isJewellery ? (supEditForm.jewellery_type || null) : null,
      metal: isJewellery ? (supEditForm.metal || null) : null,
      stone: isJewellery ? (supEditForm.stone || null) : null,
      size_info: isJewellery ? (supEditForm.size_info || null) : null,
    }

    const { error } = await supabase
      .from('supplier_listings')
      .update(updatedFields)
      .eq('id', listingId)
    if (error) { alert('Failed to save: ' + error.message); return }

    for (const id of supEditRemovedIds) {
      await supabase.from('supplier_listing_images').delete().eq('id', id)
    }

    const startPos = supEditExistingImgs.filter(img => !supEditRemovedIds.includes(img.id)).length
    for (let i = 0; i < supEditNewFiles.length; i++) {
      const file = supEditNewFiles[i]
      const ext = file.name.split('.').pop()
      const path = `supplier_listings/${listingId}/${Date.now()}_${i}.${ext}`
      const { error: upErr } = await supabase.storage.from('watch-images').upload(path, file)
      if (upErr) continue
      const { data: { publicUrl } } = supabase.storage.from('watch-images').getPublicUrl(path)
      await supabase.from('supplier_listing_images').insert({ listing_id: listingId, url: publicUrl, position: startPos + i })
    }

    // Optimistic update: immediately reflect edits in local state so the approve
    // button uses the fresh notes/fields without waiting for the DB refetch.
    setSupplierListings(prev => prev.map(l =>
      l.id === listingId ? { ...l, ...updatedFields } : l
    ))

    setSupEditId(null)
    fetchSupplierListings()
  }

